insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'Leads II, III and aVF look at the inferior wall of the left ventricle. In most people (right-dominant circulation) the inferior wall is supplied by the right coronary artery, so inferior STEMI usually reflects RCA occlusion.', 'Отведения II, III и aVF отражают нижнюю стенку левого желудочка. У большинства людей (правый тип кровоснабжения) её кровоснабжает правая коронарная артерия, поэтому нижний инфаркт с подъёмом ST обычно связан с окклюзией ПКА.', 'Think of the leads as cameras: II, III and aVF all view the inferior wall. Which artery usually feeds that wall in a right-dominant heart?', '{"A":"LAD occlusion causes anterior ST elevation (V1–V4), not inferior.","C":"The circumflex causes lateral changes (I, aVL, V5–V6); it supplies the inferior wall only in the minority with left-dominant circulation.","D":"Left main occlusion typically causes widespread ST depression with ST elevation in aVR and rapid haemodynamic collapse."}'::jsonb, 'In inferior STEMI, record right-sided leads (V4R): right-ventricular infarction makes the patient preload-dependent, so avoid nitrates.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-card-02', 'cardiology', 'Arrhythmias', 'Supraventricular tachycardia', 'Acute management', 2, 'A haemodynamically stable 30-year-old woman has a regular narrow-complex tachycardia at 190/min. Vagal manoeuvres have failed. What is the most appropriate next drug?', 'У гемодинамически стабильной женщины 30 лет регулярная тахикардия с узкими комплексами QRS, ЧСС 190 в минуту. Вагусные пробы неэффективны. Какой препарат наиболее целесообразен?', '[{"ru":"вагусные пробы","en":"vagal manoeuvres"},{"ru":"тахикардия с узкими комплексами","en":"narrow-complex tachycardia"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Adenosine IV bolus', 'Аденозин внутривенно болюсно'), ('B', 'Atropine IV', 'Атропин внутривенно'), ('C', 'Oral digoxin', 'Дигоксин внутрь'), ('D', 'Synchronised cardioversion', 'Синхронизированная кардиоверсия')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'A regular narrow-complex tachycardia in a stable patient is most often AV-nodal re-entry. After vagal manoeuvres fail, a rapid IV bolus of adenosine transiently blocks the AV node and usually terminates it.', null, 'Stable + regular + narrow = re-entry through the AV node. Which drug briefly blocks the AV node?', '{"B":"Atropine speeds AV conduction and heart rate; it is used for symptomatic bradycardia.","C":"Oral digoxin acts far too slowly to terminate an acute tachycardia.","D":"Synchronised cardioversion is for unstable patients (shock, syncope, ischaemia, heart failure). This patient is stable."}'::jsonb, 'Give adenosine as a rapid bolus followed immediately by a saline flush through a large proximal vein, and warn the patient about brief chest discomfort.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-card-03', 'cardiology', 'Heart failure', 'Chronic heart failure', 'Prognostic therapy', 2, 'A 66-year-old man has chronic heart failure with a left-ventricular ejection fraction of 30%. He is on furosemide and ramipril. Which additional drug has been shown to improve survival?', 'У мужчины 66 лет хроническая сердечная недостаточность с фракцией выброса левого желудочка 30%. Он принимает фуросемид и рамиприл. Какой дополнительный препарат доказанно улучшает выживаемость?', '[{"ru":"фракция выброса","en":"ejection fraction"},{"ru":"хроническая сердечная недостаточность","en":"chronic heart failure"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Digoxin', 'Дигоксин'), ('B', 'Amlodipine', 'Амлодипин'), ('C', 'Bisoprolol', 'Бисопролол'), ('D', 'Increasing the furosemide dose', 'Увеличение дозы фуросемида')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'C', 'Evidence-based beta-blockers (bisoprolol, carvedilol, metoprolol succinate) reduce mortality in heart failure with reduced ejection fraction. Start low and titrate slowly once the patient is euvolaemic.', null, 'Separate drugs that make patients feel better from drugs that make them live longer.', '{"A":"Digoxin reduces hospital admissions but does not improve survival.","B":"Amlodipine is neutral for mortality in heart failure; it may be used for hypertension or angina but is not prognostic.","D":"Loop diuretics relieve congestion and symptoms but do not improve survival."}'::jsonb, 'The four pillars of HFrEF therapy: ACE inhibitor/ARB/ARNI, an evidence-based beta-blocker, a mineralocorticoid receptor antagonist and an SGLT2 inhibitor.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-card-04', 'cardiology', 'Valvular and infective heart disease', 'Infective endocarditis', 'Microbiology', 1, 'A 29-year-old man who injects drugs has fever for 5 days, a new pansystolic murmur at the left lower sternal edge and multiple lung nodules on chest X-ray. Which organism is most likely?', 'У мужчины 29 лет, употребляющего внутривенные наркотики, 5 дней лихорадка, новый пансистолический шум у левого края грудины внизу и множественные очаги в лёгких на рентгенограмме. Какой возбудитель наиболее вероятен?', '[{"ru":"инфекционный эндокардит","en":"infective endocarditis"},{"ru":"трикуспидальный клапан","en":"tricuspid valve"},{"ru":"септические эмболы","en":"septic emboli"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Viridans group streptococci', 'Зеленящие стрептококки'), ('B', 'Enterococcus faecalis', 'Enterococcus faecalis'), ('C', 'Staphylococcus epidermidis', 'Staphylococcus epidermidis'), ('D', 'Staphylococcus aureus', 'Staphylococcus aureus')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'D', 'Right-sided (tricuspid) endocarditis in people who inject drugs is most often caused by Staphylococcus aureus. Septic emboli to the lungs explain the nodules.', null, 'Injecting drugs + tricuspid murmur + lung emboli: think of the skin organism that is most virulent.', '{"A":"Viridans streptococci typically cause subacute endocarditis on abnormal native left-sided valves, often after dental procedures.","B":"Enterococci are associated with older patients and gastrointestinal or urinary tract procedures.","C":"Coagulase-negative staphylococci mainly infect prosthetic valves and devices, especially early after surgery."}'::jsonb, 'Take at least three sets of blood cultures from separate venepunctures before starting antibiotics.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-pulm-01', 'pulmonology', 'Pleural disease', 'Pleural effusion', 'Light''s criteria', 2, 'A pleural fluid sample is analysed. Which finding indicates that the effusion is an exudate according to Light''s criteria?', 'Проведён анализ плевральной жидкости. Какой показатель свидетельствует об экссудате согласно критериям Лайта?', '[{"ru":"плевральный выпот","en":"pleural effusion"},{"ru":"экссудат","en":"exudate"},{"ru":"транссудат","en":"transudate"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Pleural fluid / serum protein ratio of 0.3', 'Отношение белка плевральной жидкости к белку сыворотки 0,3'), ('B', 'Pleural fluid / serum protein ratio greater than 0.5', 'Отношение белка плевральной жидкости к белку сыворотки более 0,5'), ('C', 'Pleural fluid / serum LDH ratio of 0.4', 'Отношение ЛДГ плевральной жидкости к ЛДГ сыворотки 0,4'), ('D', 'Pleural LDH below two-thirds of the serum upper limit of normal', 'ЛДГ плевральной жидкости менее 2/3 верхней границы нормы сыворотки')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'An effusion is an exudate if ANY of these is true: pleural/serum protein > 0.5, pleural/serum LDH > 0.6, or pleural LDH > two-thirds of the upper limit of normal for serum LDH.', 'Выпот считается экссудатом, если выполняется ЛЮБОЙ критерий: отношение белка плевральной жидкости к сывороточному > 0,5; отношение ЛДГ > 0,6; ЛДГ плевральной жидкости > 2/3 верхней границы нормы сывороточной ЛДГ.', 'Remember the three numbers: 0.5, 0.6 and two-thirds.', '{"A":"A protein ratio of 0.3 is below the 0.5 threshold, which fits a transudate.","C":"An LDH ratio of 0.4 is below the 0.6 threshold.","D":"Pleural LDH below two-thirds of the upper limit is on the transudate side."}'::jsonb, 'Light''s criteria are very sensitive for exudates and can misclassify heart-failure effusions after diuretics; a serum–pleural albumin gradient > 12 g/L then supports a transudate.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-pulm-02', 'pulmonology', 'Pleural disease', 'Pneumothorax', 'Clinical diagnosis', 1, 'A tall, thin 22-year-old man develops sudden right-sided pleuritic chest pain and breathlessness. On the right, breath sounds are absent and percussion is hyperresonant. What is the most likely diagnosis?', 'У высокого худощавого мужчины 22 лет внезапно возникли боль в правой половине грудной клетки, усиливающаяся при дыхании, и одышка. Справа дыхание не проводится, перкуторно — коробочный звук. Наиболее вероятный диагноз?', '[{"ru":"пневмоторакс","en":"pneumothorax"},{"ru":"коробочный звук","en":"hyperresonant percussion note"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Lobar pneumonia', 'Долевая пневмония'), ('B', 'Pleural effusion', 'Плевральный выпот'), ('C', 'Primary spontaneous pneumothorax', 'Первичный спонтанный пневмоторакс'), ('D', 'Pulmonary embolism', 'Тромбоэмболия лёгочной артерии')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'C', 'Primary spontaneous pneumothorax typically affects tall, thin young men without lung disease. Air in the pleural space gives absent breath sounds with a hyperresonant percussion note.', null, 'Percussion decides it: dull means fluid or consolidation; hyperresonant means air.', '{"A":"Consolidation is dull to percussion, with bronchial breathing and usually fever.","B":"Fluid gives a stony-dull percussion note, not hyperresonance.","D":"Pulmonary embolism causes pleuritic pain and breathlessness, but the chest examination is usually normal."}'::jsonb, 'Tension pneumothorax is a clinical diagnosis: decompress immediately, without waiting for an X-ray.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-pulm-03', 'pulmonology', 'Obstructive airway disease', 'Asthma', 'Acute exacerbation', 1, 'A 24-year-old woman with asthma has a severe attack: she cannot complete sentences, respiratory rate is 30/min and peak flow is 40% of her best. After oxygen, what is the first-line treatment?', 'У женщины 24 лет с бронхиальной астмой тяжёлое обострение: не может закончить фразу, ЧДД 30 в минуту, пиковая скорость выдоха 40% от лучшего значения. Что назначают в первую очередь после кислорода?', '[{"ru":"бронхиальная астма","en":"bronchial asthma"},{"ru":"пиковая скорость выдоха","en":"peak expiratory flow"},{"ru":"обострение","en":"exacerbation"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'IV magnesium sulfate', 'Магния сульфат внутривенно'), ('B', 'High-dose nebulised salbutamol', 'Сальбутамол через небулайзер в высокой дозе'), ('C', 'Oral montelukast', 'Монтелукаст внутрь'), ('D', 'IV aminophylline', 'Аминофиллин внутривенно')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'High-dose inhaled short-acting β2-agonist (salbutamol by nebuliser, driven by oxygen) is first-line, together with systemic corticosteroids. Ipratropium is added in severe attacks.', null, 'Open the airways fast, with the drug that works in minutes.', '{"A":"IV magnesium is an add-on for severe attacks that do not respond to initial bronchodilator therapy.","C":"Leukotriene antagonists are maintenance drugs with no role in treating an acute attack.","D":"Aminophylline is not first-line: it adds little benefit and has a narrow therapeutic window. Senior advice is needed."}'::jsonb, 'In acute asthma, a normal or rising PaCO₂ means the patient is tiring. It is a life-threatening sign, so involve intensive care early.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-pulm-04', 'pulmonology', 'Obstructive airway disease', 'COPD', 'Long-term management', 2, 'A 70-year-old ex-smoker with COPD has a resting PaO₂ of 6.9 kPa (52 mmHg) on two measurements 3 weeks apart while clinically stable. Which intervention improves his survival?', 'У мужчины 70 лет, бывшего курильщика с ХОБЛ, в стабильном состоянии дважды с интервалом 3 недели PaO₂ в покое 6,9 кПа (52 мм рт. ст.). Какое вмешательство улучшает выживаемость?', '[{"ru":"ХОБЛ","en":"COPD"},{"ru":"длительная кислородотерапия","en":"long-term oxygen therapy"},{"ru":"гипоксемия","en":"hypoxaemia"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
