insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'C', 'In COPD with chronic hypoxaemia (PaO₂ ≤ 7.3 kPa / 55 mmHg when stable), long-term oxygen therapy for at least 15 hours a day prolongs survival.', null, 'Which treatment corrects the chronic problem in his blood gas?', '{"A":"Inhaled corticosteroids alone do not improve survival and increase pneumonia risk; they are combined with long-acting bronchodilators in selected patients.","B":"Long-term oral steroids cause significant harm (myopathy, osteoporosis, diabetes) without survival benefit.","D":"Mucolytics may reduce exacerbations in some patients but do not improve survival."}'::jsonb, 'Two interventions are shown to prolong life in COPD: stopping smoking and long-term oxygen therapy for chronic hypoxaemia.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-neuro-01', 'neurology', 'Cerebrovascular disease', 'Subarachnoid haemorrhage', 'Investigation', 1, 'A 45-year-old woman reports a sudden, severe ''worst-ever'' headache followed by vomiting and neck stiffness. What is the first investigation?', 'Женщина 45 лет жалуется на внезапную интенсивную головную боль («самую сильную в жизни»), рвоту и ригидность затылочных мышц. Какое исследование проводится в первую очередь?', '[{"ru":"субарахноидальное кровоизлияние","en":"subarachnoid haemorrhage"},{"ru":"ригидность затылочных мышц","en":"neck stiffness"},{"ru":"ксантохромия","en":"xanthochromia"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Non-contrast CT of the head', 'КТ головного мозга без контрастирования'), ('B', 'Electroencephalography', 'Электроэнцефалография'), ('C', 'Skull X-ray', 'Рентгенография черепа'), ('D', 'Lumbar puncture before any imaging', 'Люмбальная пункция до нейровизуализации')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'A sudden ''thunderclap'' headache suggests subarachnoid haemorrhage. Non-contrast CT is the first investigation. If it is negative but suspicion remains, lumbar puncture is done later, looking for xanthochromia.', null, 'Imaging before needles.', '{"B":"EEG assesses seizure activity and does not detect haemorrhage.","C":"A skull X-ray cannot show intracranial blood.","D":"Imaging comes first: LP before CT risks herniation if there is a mass lesion, and xanthochromia needs time (about 12 hours) to develop."}'::jsonb, 'CT is most sensitive for subarachnoid blood within the first 6 hours of headache onset; sensitivity falls over the following days.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-neuro-02', 'neurology', 'Cerebrovascular disease', 'Ischaemic stroke', 'Vascular localisation', 2, 'A right-handed man suddenly develops right-sided weakness affecting the face and arm more than the leg, with non-fluent speech but preserved comprehension. Which vascular territory is affected?', 'У мужчины-правши внезапно развилась слабость в правых конечностях (рука и лицо больше, чем нога), речь прерывистая, с трудом подбирает слова, понимание обращённой речи сохранено. Какой сосудистый бассейн поражён?', '[{"ru":"моторная афазия","en":"expressive (Broca''s) aphasia"},{"ru":"гемипарез","en":"hemiparesis"},{"ru":"ишемический инсульт","en":"ischaemic stroke"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Right middle cerebral artery', 'Правая средняя мозговая артерия'), ('B', 'Left middle cerebral artery', 'Левая средняя мозговая артерия'), ('C', 'Left anterior cerebral artery', 'Левая передняя мозговая артерия'), ('D', 'Basilar artery', 'Основная артерия')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'Face and arm weakness greater than leg weakness indicates the middle cerebral artery territory. Expressive (Broca''s) aphasia means the dominant hemisphere, which is the left in nearly all right-handed people.', null, 'Two steps: which side (opposite the weakness), then which artery (face + arm > leg is MCA).', '{"A":"A right MCA stroke causes LEFT-sided weakness, often with neglect rather than aphasia.","C":"ACA strokes affect the leg more than the arm and face, often with behavioural change.","D":"Basilar occlusion causes bilateral signs, cranial nerve palsies and reduced consciousness."}'::jsonb, 'Establish when the patient was last seen well: it decides eligibility for thrombolysis and thrombectomy.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-neuro-03', 'neurology', 'Neuromuscular disease', 'Myasthenia gravis', 'Diagnosis', 2, 'A 34-year-old woman has drooping eyelids and double vision that are worse in the evening and improve after rest. Strength in the arms decreases with repeated effort. Which antibody test best supports the likely diagnosis?', 'У женщины 34 лет опущение век и двоение в глазах, усиливающиеся к вечеру и уменьшающиеся после отдыха. Сила в руках снижается при повторных усилиях. Определение каких антител лучше всего подтвердит вероятный диагноз?', '[{"ru":"миастения","en":"myasthenia gravis"},{"ru":"птоз","en":"ptosis"},{"ru":"диплопия","en":"diplopia"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Anti-acetylcholine receptor antibodies', 'Антитела к ацетилхолиновым рецепторам'), ('B', 'Anti-voltage-gated calcium channel antibodies', 'Антитела к потенциалзависимым кальциевым каналам'), ('C', 'Anti-GQ1b antibodies', 'Антитела к ганглиозиду GQ1b'), ('D', 'Anti-aquaporin-4 antibodies', 'Антитела к аквапорину-4')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'Fatigable weakness affecting the eyes first, worse later in the day, is typical of myasthenia gravis. Acetylcholine receptor antibodies are found in most patients with generalised disease.', null, 'Weakness that worsens with use points to the neuromuscular junction, on the postsynaptic side.', '{"B":"VGCC antibodies indicate Lambert–Eaton syndrome: proximal weakness that improves with repeated effort, often with autonomic features and small-cell lung cancer.","C":"Anti-GQ1b antibodies are associated with Miller Fisher syndrome (ophthalmoplegia, ataxia, areflexia).","D":"Aquaporin-4 antibodies indicate neuromyelitis optica spectrum disorder (optic neuritis and myelitis)."}'::jsonb, 'Every patient newly diagnosed with myasthenia gravis needs CT of the chest to look for a thymoma.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-neuro-04', 'neurology', 'Epilepsy', 'Status epilepticus', 'Emergency treatment', 2, 'A 40-year-old man in the emergency department has had a generalised tonic-clonic seizure lasting 6 minutes. IV access is established and glucose is normal. What is the first-line drug?', 'У мужчины 40 лет в приёмном отделении генерализованный тонико-клонический приступ длится 6 минут. Внутривенный доступ установлен, глюкоза в норме. Какой препарат первой линии?', '[{"ru":"эпилептический статус","en":"status epilepticus"},{"ru":"судороги","en":"seizures"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'IV levetiracetam', 'Леветирацетам внутривенно'), ('B', 'IV benzodiazepine (lorazepam or diazepam)', 'Бензодиазепин внутривенно (лоразепам или диазепам)'), ('C', 'IV phenytoin', 'Фенитоин внутривенно'), ('D', 'General anaesthesia with thiopental', 'Общая анестезия тиопенталом')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'A seizure lasting 5 minutes or more is treated as status epilepticus. An IV benzodiazepine is first-line; a second-line anticonvulsant follows if seizures continue.', null, 'Stop the seizure fast first; loading a longer-acting drug comes second.', '{"A":"Levetiracetam is a second-line agent, given if seizures continue after benzodiazepines.","C":"Phenytoin is also second-line and needs cardiac monitoring during infusion.","D":"General anaesthesia is reserved for refractory status epilepticus that persists after second-line drugs."}'::jsonb, 'If seizures continue after two doses of benzodiazepine, move to a second-line drug; don''t keep repeating benzodiazepines.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-01', 'endocrinology', 'Diabetes mellitus', 'Diabetic ketoacidosis', 'Initial management', 2, 'A 19-year-old with type 1 diabetes presents with vomiting, Kussmaul breathing, glucose 28 mmol/L and pH 7.1. What is the most important first step in management?', 'Пациент 19 лет с сахарным диабетом 1 типа поступил с рвотой, дыханием Куссмауля, глюкозой 28 ммоль/л и pH 7,1. Какое первоочередное мероприятие наиболее важно?', '[{"ru":"диабетический кетоацидоз","en":"diabetic ketoacidosis"},{"ru":"дыхание Куссмауля","en":"Kussmaul breathing"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'IV 0.9% sodium chloride', 'Внутривенное введение 0,9% раствора натрия хлорида'), ('B', 'Routine IV sodium bicarbonate', 'Рутинное внутривенное введение натрия гидрокарбоната'), ('C', 'Subcutaneous insulin glargine alone', 'Только подкожное введение инсулина гларгин'), ('D', 'Oral rehydration solution', 'Пероральная регидратация')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'Patients in DKA are severely volume-depleted. The first priority is IV isotonic fluid, followed by a fixed-rate IV insulin infusion and careful potassium replacement.', 'При диабетическом кетоацидозе выражена дегидратация. Первоочередная задача — внутривенная инфузия изотонического раствора, затем внутривенная инфузия инсулина с фиксированной скоростью и тщательное восполнение калия.', 'Fluids first, then insulin, and watch potassium throughout.', '{"B":"Bicarbonate is not routinely recommended: it can worsen hypokalaemia and, in children, is linked to cerebral oedema.","C":"Subcutaneous long-acting insulin alone is inadequate acutely; IV insulin is needed (basal insulin may be continued alongside).","D":"A vomiting, severely dehydrated patient cannot be rehydrated by mouth."}'::jsonb, 'Check potassium before starting insulin: if K⁺ is below 3.5 mmol/L, replace it first, because insulin drives potassium into cells.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-02', 'endocrinology', 'Thyroid disease', 'Hypothyroidism', 'Laboratory diagnosis', 1, 'Which laboratory pattern is typical of primary hypothyroidism?', 'Какие лабораторные показатели характерны для первичного гипотиреоза?', '[{"ru":"гипотиреоз","en":"hypothyroidism"},{"ru":"тиреотропный гормон (ТТГ)","en":"thyroid-stimulating hormone (TSH)"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Low TSH, high free T4', 'ТТГ снижен, свободный T4 повышен'), ('B', 'High TSH, low free T4', 'ТТГ повышен, свободный T4 снижен'), ('C', 'Low TSH, low free T4', 'ТТГ снижен, свободный T4 снижен'), ('D', 'Normal TSH, high free T4', 'ТТГ в норме, свободный T4 повышен')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'In primary hypothyroidism the thyroid itself fails, so free T4 falls and the pituitary responds by increasing TSH.', null, 'Follow the feedback loop: when the gland fails, the pituitary ''shouts louder''.', '{"A":"Low TSH with high free T4 is the pattern of primary hyperthyroidism.","C":"Low TSH with low free T4 suggests secondary (central) hypothyroidism or non-thyroidal illness.","D":"Normal TSH with high free T4 suggests assay interference or rare causes such as a TSH-secreting adenoma."}'::jsonb, 'In central hypothyroidism, TSH can''t be used to monitor treatment; titrate levothyroxine to free T4 instead.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-03', 'endocrinology', 'Adrenal disease', 'Adrenal insufficiency', 'Adrenal crisis', 2, 'A 38-year-old woman with weeks of fatigue, weight loss and darkening skin presents with vomiting and BP 75/40 mmHg. Sodium is 124 mmol/L and potassium 6.1 mmol/L. After taking blood for cortisol, what is the most urgent treatment?', 'Женщина 38 лет с многонедельной слабостью, похуданием и потемнением кожи поступила с рвотой, АД 75/40 мм рт. ст. Натрий 124 ммоль/л, калий 6,1 ммоль/л. Какое лечение наиболее срочно после забора крови на кортизол?', '[{"ru":"надпочечниковая недостаточность","en":"adrenal insufficiency"},{"ru":"гиперпигментация","en":"hyperpigmentation"},{"ru":"гиперкалиемия","en":"hyperkalaemia"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'IV hydrocortisone 100 mg with IV saline', 'Гидрокортизон 100 мг внутривенно и инфузия физиологического раствора'), ('B', 'Oral fludrocortisone', 'Флудрокортизон внутрь'), ('C', 'IV levothyroxine', 'Левотироксин внутривенно'), ('D', 'Wait for a synacthen test result before treating', 'Дождаться результата пробы с синактеном перед лечением')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'Hypotension, hyponatraemia, hyperkalaemia and hyperpigmentation suggest adrenal crisis from primary adrenal insufficiency. Give IV hydrocortisone immediately, with fluid resuscitation.', null, 'Low sodium + high potassium + shock + pigmentation: which hormone is missing?', '{"B":"Fludrocortisone replaces mineralocorticoid long term; it is too slow and does not replace cortisol in a crisis.","C":"Thyroid hormone is not indicated, and giving it before steroids in combined deficiency can precipitate crisis.","D":"Testing must never delay treatment in suspected adrenal crisis; it can be done after stabilisation."}'::jsonb, 'Never delay steroids in suspected adrenal crisis: take a cortisol (± ACTH) sample, then give hydrocortisone straight away.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-endo-04', 'endocrinology', 'Diabetes mellitus', 'Type 2 diabetes', 'Pharmacotherapy', 1, 'A 52-year-old with newly diagnosed type 2 diabetes has HbA1c 7.8% (62 mmol/mol) despite lifestyle changes. Kidney function is normal and there is no cardiovascular or kidney disease. Which drug is usually started first?', 'У пациента 52 лет с впервые выявленным сахарным диабетом 2 типа HbA1c 7,8% (62 ммоль/моль), несмотря на изменение образа жизни. Функция почек в норме, сердечно-сосудистых заболеваний и болезней почек нет. Какой препарат обычно назначают первым?', '[{"ru":"сахарный диабет 2 типа","en":"type 2 diabetes mellitus"},{"ru":"гликированный гемоглобин","en":"glycated haemoglobin (HbA1c)"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Insulin glargine', 'Инсулин гларгин'), ('B', 'Gliclazide', 'Гликлазид'), ('C', 'Metformin', 'Метформин'), ('D', 'Pioglitazone', 'Пиоглитазон')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'C', 'Metformin is the usual first-line drug: effective, weight-neutral, low risk of hypoglycaemia and inexpensive. Check kidney function first.', null, 'Pick the drug with the best balance of effectiveness, safety and cost for an uncomplicated patient.', '{"A":"Insulin is reserved for marked hyperglycaemia, catabolic symptoms or failure of other therapy.","B":"Sulfonylureas cause hypoglycaemia and weight gain; they are usually second-line.","D":"Pioglitazone causes weight gain and fluid retention, and is avoided in heart failure."}'::jsonb, 'In patients with established cardiovascular disease, heart failure or chronic kidney disease, add an SGLT2 inhibitor or GLP-1 receptor agonist with proven benefit, whatever the HbA1c.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-em-01', 'emergency-medicine', 'Shock', 'Anaphylaxis', 'Immediate treatment', 1, 'Ten minutes after a wasp sting, a 30-year-old man has widespread urticaria, lip swelling, wheeze and BP 80/50 mmHg. What is the first drug to give?', 'Через 10 минут после ужаления осой у мужчины 30 лет генерализованная крапивница, отёк губ, свистящее дыхание, АД 80/50 мм рт. ст. Какой препарат вводят первым?', '[{"ru":"анафилаксия","en":"anaphylaxis"},{"ru":"крапивница","en":"urticaria"},{"ru":"отёк Квинке","en":"angioedema"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Adrenaline 0.5 mg intramuscularly', 'Адреналин (эпинефрин) 0,5 мг внутримышечно'), ('B', 'Chlorphenamine IV', 'Хлорфенамин внутривенно'), ('C', 'Hydrocortisone IV', 'Гидрокортизон внутривенно'), ('D', 'Nebulised salbutamol', 'Сальбутамол через небулайзер')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'A', 'Anaphylaxis is treated first with intramuscular adrenaline (0.5 mg of 1 mg/mL for adults, into the anterolateral thigh), plus airway support, oxygen and IV fluids for hypotension.', 'При анафилаксии первым вводят адреналин внутримышечно (взрослым 0,5 мг раствора 1 мг/мл в переднебоковую поверхность бедра), одновременно обеспечивают проходимость дыхательных путей, кислород и инфузию при гипотензии.', 'Only one drug treats airway swelling, bronchospasm and shock at the same time.', '{"B":"Antihistamines only treat skin symptoms; they do not reverse airway swelling or shock.","C":"Corticosteroids act too slowly for the emergency and are not first-line.","D":"Salbutamol can help residual wheeze, but only after adrenaline."}'::jsonb, 'If there is no improvement, repeat IM adrenaline after 5 minutes; don''t wait for IV access to give the first dose.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-em-02', 'emergency-medicine', 'Resuscitation', 'Cardiac arrest', 'Shockable rhythms', 1, 'During CPR for an unresponsive patient, the defibrillator shows ventricular fibrillation. What is the immediate next step?', 'Во время сердечно-лёгочной реанимации у пациента без сознания на мониторе дефибриллятора — фибрилляция желудочков. Какое следующее действие?', '[{"ru":"фибрилляция желудочков","en":"ventricular fibrillation"},{"ru":"сердечно-лёгочная реанимация","en":"cardiopulmonary resuscitation"},{"ru":"дефибрилляция","en":"defibrillation"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Give IV adrenaline 1 mg', 'Ввести адреналин 1 мг внутривенно'), ('B', 'Deliver a defibrillator shock', 'Нанести разряд дефибриллятора'), ('C', 'Give IV amiodarone 300 mg', 'Ввести амиодарон 300 мг внутривенно'), ('D', 'Check the carotid pulse for 30 seconds', 'Проверить пульс на сонной артерии в течение 30 секунд')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'B', 'VF is a shockable rhythm: deliver a shock as soon as possible, then immediately resume chest compressions for 2 minutes before reassessing the rhythm.', null, 'Shockable rhythm: what single action changes the outcome most?', '{"A":"In shockable rhythms, adrenaline is given after the third shock, not before the first.","C":"Amiodarone is given after the third shock for persistent VF or pulseless VT.","D":"Pulse checks must be brief (under 10 seconds) and never delay defibrillation."}'::jsonb, 'Minimise pauses in chest compressions: restart CPR straight after each shock, without checking for a pulse.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-em-03', 'emergency-medicine', 'Toxicology', 'Paracetamol poisoning', 'Antidotes', 1, 'A 19-year-old took 40 tablets of paracetamol 500 mg six hours ago. Her paracetamol level is above the treatment line. Which treatment is indicated?', 'Девушка 19 лет 6 часов назад приняла 40 таблеток парацетамола по 500 мг. Концентрация парацетамола выше линии лечения. Какое лечение показано?', '[{"ru":"отравление парацетамолом","en":"paracetamol poisoning"},{"ru":"антидот","en":"antidote"},{"ru":"печёночная недостаточность","en":"liver failure"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Naloxone', 'Налоксон'), ('B', 'Flumazenil', 'Флумазенил'), ('C', 'Activated charcoal alone', 'Только активированный уголь'), ('D', 'Acetylcysteine', 'Ацетилцистеин')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'D', 'Acetylcysteine replenishes glutathione and prevents liver injury from the toxic paracetamol metabolite (NAPQI). It is most effective within 8 hours but is still given later.', null, 'Which drug restores the liver''s own detoxifying capacity?', '{"A":"Naloxone reverses opioids, not paracetamol.","B":"Flumazenil reverses benzodiazepines and is rarely used because it can trigger seizures.","C":"Activated charcoal helps only within about 1 hour of ingestion and is not an antidote."}'::jsonb, 'Use a paracetamol level taken at least 4 hours after ingestion; for staggered or uncertain-time overdoses, treat without waiting for the nomogram.' from q;

with q as (insert into public.questions (slug, topic, subject, clinical_topic, subtopic, difficulty, stem_en, stem_ru, key_terms, origin, source_ref, rights_status, review_status, review_note) values ('q-em-04', 'emergency-medicine', 'Toxicology', 'Opioid toxicity', 'Reversal', 1, 'A man is found drowsy with pinpoint pupils and a respiratory rate of 6/min. A used syringe is nearby. After airway support and ventilation, which drug should be given?', 'Мужчина обнаружен в оглушении, зрачки точечные, ЧДД 6 в минуту, рядом использованный шприц. Какой препарат следует ввести после обеспечения проходимости дыхательных путей и вентиляции?', '[{"ru":"передозировка опиоидов","en":"opioid overdose"},{"ru":"миоз","en":"miosis"},{"ru":"угнетение дыхания","en":"respiratory depression"}]'::jsonb, 'demo', 'MedPrep illustrative demo set (original)', 'owned', 'draft', 'Illustrative only. Not yet validated by a qualified medical reviewer.') returning id),
o as (insert into public.question_options (question_id, position, text_en, text_ru) select q.id, v.p, v.en, v.ru from q, (values ('A', 'Flumazenil', 'Флумазенил'), ('B', 'Atropine', 'Атропин'), ('C', 'Naloxone', 'Налоксон'), ('D', 'Physostigmine', 'Физостигмин')) as v(p, en, ru))
insert into public.question_keys (question_id, correct, explanation_en, explanation_ru, tutor_hint, option_explanations, exam_pearl) select q.id, 'C', 'Reduced consciousness, pinpoint pupils and respiratory depression are the opioid toxidrome. Naloxone, a competitive opioid antagonist, reverses it, titrated to adequate breathing.', null, 'Name the toxidrome from the pupils and the breathing, then pick its antagonist.', '{"A":"Flumazenil reverses benzodiazepines, which do not usually cause pinpoint pupils.","B":"Atropine treats organophosphate poisoning (small pupils with excessive secretions, sweating and bradycardia), not opioid toxicity.","D":"Physostigmine is used for anticholinergic toxicity, which causes dilated pupils."}'::jsonb, 'Naloxone''s effect wears off sooner than many opioids: observe for recurrent sedation and repeat doses or start an infusion if needed.' from q;
